import { readFile, readdir, mkdir, writeFile } from 'node:fs/promises'
import { join } from 'node:path'

const root = process.cwd()
const sourceDir = join(root, 'migrations')
const outputDir = join(root, 'supabase', 'migrations')
const outputFile = join(outputDir, '202609030001_cloudflare_to_supabase.sql')

const files = (await readdir(sourceDir))
  .filter((name) => /^\d{4}_.+\.sql$/.test(name))
  .sort()

let body = ''
for (const file of files) {
  let sql = await readFile(join(sourceDir, file), 'utf8')
  sql = sql.replaceAll(
    'INTEGER PRIMARY KEY AUTOINCREMENT',
    'BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY'
  )
  body += `\n-- ${file}\n${sql.trim()}\n`
}

// PostgreSQL expression indexes require each CASE expression to be wrapped.
body = body.replace(
  /CREATE INDEX idx_dm_pair ON direct_messages\(\s*CASE WHEN sender_id < recipient_id THEN sender_id ELSE recipient_id END,\s*CASE WHEN sender_id < recipient_id THEN recipient_id ELSE sender_id END,\s*id\s*\);/m,
  `CREATE INDEX idx_dm_pair ON direct_messages(
  (CASE WHEN sender_id < recipient_id THEN sender_id ELSE recipient_id END),
  (CASE WHEN sender_id < recipient_id THEN recipient_id ELSE sender_id END),
  id
);`
)

const tables = [...body.matchAll(/CREATE TABLE(?: IF NOT EXISTS)?\s+([a-z_][a-z0-9_]*)/gi)]
  .map((match) => match[1])
  .filter((table, index, all) => all.indexOf(table) === index)

const header = `-- Generated from migrations/*.sql by scripts/build-supabase-migration.mjs.
-- Business columns intentionally stay TEXT/INTEGER compatible with the existing API.
BEGIN;

CREATE OR REPLACE FUNCTION public.datetime()
RETURNS TEXT
LANGUAGE SQL
STABLE
AS $$
  SELECT to_char(timezone('utc', now()), 'YYYY-MM-DD HH24:MI:SS');
$$;

CREATE OR REPLACE FUNCTION public.datetime(value TEXT)
RETURNS TEXT
LANGUAGE SQL
STABLE
AS $$
  SELECT to_char(
    timezone('utc', CASE WHEN value IS NULL OR lower(value) = 'now' THEN now() ELSE value::timestamptz END),
    'YYYY-MM-DD HH24:MI:SS'
  );
$$;

CREATE OR REPLACE FUNCTION public.datetime(value TEXT, modifier TEXT)
RETURNS TEXT
LANGUAGE SQL
STABLE
AS $$
  SELECT to_char(
    timezone(
      'utc',
      (CASE WHEN value IS NULL OR lower(value) = 'now' THEN now() ELSE value::timestamptz END)
        + COALESCE(NULLIF(modifier, ''), '0 seconds')::interval
    ),
    'YYYY-MM-DD HH24:MI:SS'
  );
$$;

CREATE OR REPLACE FUNCTION public.datetime(value TEXT, modifier_one TEXT, modifier_two TEXT)
RETURNS TEXT
LANGUAGE SQL
STABLE
AS $$
  SELECT to_char(
    timezone(
      'utc',
      (CASE WHEN value IS NULL OR lower(value) = 'now' THEN now() ELSE value::timestamptz END)
        + COALESCE(NULLIF(modifier_one, ''), '0 seconds')::interval
        + COALESCE(NULLIF(modifier_two, ''), '0 seconds')::interval
    ),
    'YYYY-MM-DD HH24:MI:SS'
  );
$$;

CREATE OR REPLACE FUNCTION public.date(value TEXT, modifier TEXT)
RETURNS TEXT
LANGUAGE SQL
STABLE
AS $$
  SELECT to_char(
    timezone(
      'utc',
      (CASE WHEN value IS NULL OR lower(value) = 'now' THEN now() ELSE value::timestamptz END)
        + COALESCE(NULLIF(modifier, ''), '0 seconds')::interval
    ),
    'YYYY-MM-DD'
  );
$$;

CREATE OR REPLACE FUNCTION public.julianday(value TEXT)
RETURNS DOUBLE PRECISION
LANGUAGE SQL
STABLE
AS $$
  SELECT extract(epoch FROM value::timestamptz) / 86400.0 + 2440587.5;
$$;

CREATE OR REPLACE FUNCTION public.json_array_length(value TEXT)
RETURNS INTEGER
LANGUAGE SQL
IMMUTABLE
AS $$
  SELECT jsonb_array_length(COALESCE(NULLIF(value, ''), '[]')::jsonb);
$$;
`

const footer = `
-- The browser never queries these tables directly. Only the Edge Function's
-- server-side Postgres connection may read or write business data.
${tables.map((table) => `ALTER TABLE public.${table} ENABLE ROW LEVEL SECURITY;`).join('\n')}

REVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon, authenticated;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM anon, authenticated;

INSERT INTO storage.buckets (id, name, public, file_size_limit)
VALUES
  ('documents', 'documents', false, 10485760),
  ('interview-recordings', 'interview-recordings', false, 1073741824)
ON CONFLICT (id) DO UPDATE SET
  public = EXCLUDED.public,
  file_size_limit = EXCLUDED.file_size_limit;

COMMIT;
`

await mkdir(outputDir, { recursive: true })
await writeFile(outputFile, `${header}${body}${footer}`)
console.log(outputFile)
